import {defaults,defaultPreferences,initialControls,calculate,grossRetirementCapital} from './engine.mjs?v=20261007-funding1';
import {RULES,SOURCES} from './rules.mjs';
import {sameControls,formatMoney,deltaSentence,periodLabel,currentPriorities} from './experience.mjs';
import {timelineRows,shortfallOptions,lowerReturnScenario,fundingBreakdown,fundingSources} from './decision-support.mjs?v=20261007-funding1';
const money=formatMoney;
let profile={...defaults},prefs={...defaultPreferences},controls=initialControls(prefs),baseline={...controls},screen='welcome',question=0,chosen=null,lastChange=null,saved=false,preferencesDone=false,lastControl=null,draftPreferences={...prefs};
const app=document.querySelector('#app'),dialog=document.querySelector('#detail');
const goals=[{key:'L',title:'Life happens',colour:'#74c8c7',desc:'Money readily available for surprises and short-term needs, such as home repairs, dental costs or emergency travel.'},{key:'I',title:'Income for today',colour:'#8eaeff',desc:'Money supporting your day-to-day lifestyle and the things you want to do in retirement, including your more active early years.'},{key:'F',title:'Future & family',colour:'#c3a3e8',desc:'Money with a longer horizon: later-life needs, helping family and leaving something behind.'},{key:'E',title:'Everlasting income',colour:'#e9bd7c',desc:'Income intended to continue for life. The coloured allocation represents money set aside for a lifetime income product. Any Age Pension is additional income, not a portion of your savings.'}];
const questions=[{key:'earlyLifestyle',title:'How would you like to use your money when you first retire?',options:['Make the most of my early retirement','Enjoy a fairly even lifestyle throughout','Preserve more money for later']},{key:'emergencySecurity',title:'How important is money readily available for the unexpected?',options:['Very important','Somewhat important','I’m comfortable with a smaller buffer']},{key:'lifetimeCertainty',title:'How important is income that continues for life?',options:['Very important','Somewhat important','I value flexibility more']},{key:'liquidity',title:'How important is access to your savings if plans change?',options:['Very important','Somewhat important','I’m comfortable giving up some access for more certainty']},{key:'legacy',title:'How important is helping family later or leaving money behind?',options:['Very important','Somewhat important','Not a major priority']},{key:'laterSpending',title:'Compared with your first years, how might your spending change later?',options:['It could be lower','About the same','It could be higher']}];
const tradeoffs=[{key:'enjoy',title:'Your lifestyle over time',left:'Keep more for later',right:'Enjoy more now',hint:'Balance your early experiences with savings for later life.'},{key:'certainty',title:'Income certainty and access',left:'More flexibility',right:'More income certainty',hint:'Lifetime income means committing some savings you can otherwise access.'},{key:'buffer',title:'Room for the unexpected',left:'More money invested',right:'Bigger safety buffer',hint:'A larger reserve keeps money close, with less working for the long term.'},{key:'legacy',title:'You and your family',left:'Use more yourself',right:'Leave more behind',hint:'Keeping more for family means less spending capacity for you today.'}];
function outcome(c=controls){return calculate(profile,prefs,c)}
function showDetail(html){document.querySelector('#detailContent').innerHTML=html;const title=dialog.querySelector('h2')||dialog.querySelector('h3');if(title)title.id='dialogTitle';const intro=dialog.querySelector('p');if(intro)intro.id='dialogIntro';dialog.showModal()}
function navigate(s){screen=s;saved=false;render();window.scrollTo({top:0,behavior:'instant'});app.querySelector('h1')?.focus()}
function life(o){if(o.s.capital===0)return `<h2>Your LIFE goals</h2><p>No savings are available to allocate in this example. Your income can still include Age Pension or other income.</p><div class="lifeLegend">${goals.map(g=>`<button data-goal="${g.key}" style="--colour:${g.colour}"><b>${g.key}</b><span>${g.title}</span></button>`).join('')}</div>`;let rounded=goals.map(g=>Math.floor(o.a[g.key])),remaining=100-rounded.reduce((a,b)=>a+b,0);const order=goals.map((g,i)=>({i,r:o.a[g.key]-rounded[i]})).sort((a,b)=>b.r-a.r);for(let i=0;i<remaining;i++)rounded[order[i].i]++;return `<h2>Your LIFE priorities</h2><div class="lifeBar" aria-label="Allocation of retirement savings">${goals.map(g=>`<button style="width:${o.a[g.key]}%;--colour:${g.colour}" data-goal="${g.key}" aria-label="${g.title}, ${o.a[g.key].toFixed(1)} percent"></button>`).join('')}</div><div class="lifeLegend">${goals.map((g,i)=>`<button data-goal="${g.key}" style="--colour:${g.colour}"><b>${g.key}</b><span>${g.title}</span><strong>${rounded[i]}%</strong></button>`).join('')}</div><p class="fine" style="margin:16px 0 0">Four purposes for your money, not four separate accounts. Tap a goal to learn more.</p>`}
function pensionDetails(o){const a=o.assessment;return `<details class="pensionDetail"><summary>How Age Pension was estimated</summary><p class="fine">At retirement: ${a.limitingTest}.<br>Assessable assets: ${money(a.assessableAssets)}<br>Assessable annual income: ${money(a.assessableIncome)}<br>Assets-test result: ${money(a.assetTest)} a year<br>Income-test result: ${money(a.incomeTest)} a year<br>The lower result applies, subject to eligibility. ${a.eligibleCount===0?'Age Pension starts only when each person reaches 67.':''}</p><p class="fine">Qualifying new lifetime product: 60% of payments counted as income; 60% of purchase price counted as assets, reducing to 30% from age 85 or after five years, whichever is later. Higher surrender values or death benefits can change this.</p><p class="fine">Rules snapshot: ${RULES.asAt}. Residence eligibility assumed. Rent Assistance excluded.</p></details>`}
function projectionDetails(o){const ages=[profile.retirementAge,67,75,85,90,95].filter((v,i,all)=>all.indexOf(v)===i&&v>=profile.retirementAge).sort((a,b)=>a-b);return `<details class="projectionDetail"><summary>See the annual funding detail</summary><div class="projectionTable"><table><thead><tr><th>Age</th><th>Funded income</th><th>Account-based pension</th><th>Age Pension</th><th>Lifetime pension</th><th>Other savings / income</th><th>Unfunded</th><th>Savings at start</th></tr></thead><tbody>${ages.map(age=>{let r=o.rows.find(x=>x.age===age);if(!r)return '';const f=fundingBreakdown([r]),amount=k=>f.sources.find(s=>s.key===k).displayAmount;return `<tr><th>${age}</th><td>${money(f.displayedTotal)}</td><td>${money(amount('accountBasedIncome'))}</td><td>${money(amount('agePension'))}</td><td>${money(amount('lifetimeIncome'))}</td><td>${money(amount('otherSavingsIncome')+amount('reserveIncome')+amount('otherIncome'))}</td><td>${money(f.displayedShortfall)}</td><td>${money(r.openingAbp+r.openingCash)}</td></tr>`}).join('')}</tbody></table></div><p class="fine">Age Pension is recalculated each year as savings change. Actual savings withdrawals fund the remaining planned income. Unfunded amounts are excluded from the income total. Minimum withdrawals above planned spending are kept in accessible savings. No market fluctuations or death benefits modelled.</p></details>`}
function targetGuidance(o){const target=profile.desiredIncome;if(!target)return '';const first=o.rows[0],early=fundingBreakdown(o.rows.slice(0,10));return `<div class="targetGuidance"><strong>${o.shortfallAge?`Planned income is not fully funded from age ${o.shortfallAge}`:'Planned income is funded to age 95 in this example'}</strong><p>Your ${money(target)} target sets the starting early-retirement budget. Trade-offs can change planned spending. Each year, account-based pension and other accessible savings fund what remains after lifetime income, Age Pension and other income. ${first.shortfall>1?`First-year unfunded amount: ${money(first.shortfall)}. `:''}${early.shortfall>1?`Early annual average unfunded: ${money(early.displayedShortfall)}. `:''}Future balances include these withdrawals.</p>${o.shortfallAge?'<button class="textButton" data-shortfall>Compare ways to address the gap</button>':''}</div>`}

function incomeStory(o){const starts=o.rows.find(r=>r.agePension>0),life=o.lifetimeIncome;return `<details class="pensionDetail"><summary>What could change as you get older?</summary><p class="fine">${starts?`Your modelled Age Pension ${starts.age===profile.retirementAge?'is included from retirement':`begins at your age ${starts.age}`}. It may grow as assessable savings fall, or change if your circumstances or the rules change.`:'No Age Pension is included during this example’s projection.'} ${life>0?`The lifetime product is assumed to pay about ${money(life)} each year, adjusted for inflation, while you live. Age Pension is assessed separately and is not a fixed promise of income.`:'You haven’t committed savings to a lifetime product.'}</p><p class="fine">${o.shortfallAge?`From age ${o.shortfallAge}, available savings no longer support all the planned spending. The income shown then falls to what savings, any Age Pension, lifetime-product payments and other income can provide.`:'The planned spending is funded to age 95 under these assumptions. Different returns or spending could change that.'}</p></details>`}
function incomeTimeline(o){const rows=timelineRows(o,profile.retirementAge),max=Math.max(1,...rows.map(r=>r.plannedIncome),profile.desiredIncome||0),first=o.rows[0],pensionStart=o.rows.find(r=>r.agePension>0);return `<section class="timeline panel" aria-label="Income at key ages"><h3>Your income at key ages</h3><p class="fine">First year funded: <b>${money(first.spending)}</b>. ${first.agePension===0&&pensionStart?`Age Pension is first estimated at your age ${pensionStart.age}.`:first.agePension===0?'No Age Pension is estimated in this projection.':'Age Pension is included from retirement.'} Savings fund the remainder. Each bar shows that year, rather than an average.</p><div class="timelineLegend">${fundingSources.filter(x=>rows.some(r=>r[x.key]>0)||x.key==='accountBasedIncome').map(x=>`<span><i style="background:${x.colour}"></i>${x.label}</span>`).join('')}${rows.some(r=>r.shortfall>1)?'<span><i class="unfundedSwatch"></i>Unfunded</span>':''}</div>${rows.map(r=>{const f=fundingBreakdown([r]);return `<div class="fundingYear"><div class="timelineRow"><span>Age ${r.age}</span><div class="timelineTrack" aria-hidden="true"><div class="timelineSegments" style="width:${100*r.plannedIncome/max}%">${fundingSources.map(x=>`<i style="width:${r.plannedIncome?100*r[x.key]/r.plannedIncome:0}%;background:${x.colour}"></i>`).join('')}${r.shortfall>0?`<i class="unfundedSegment" style="width:${100*r.shortfall/r.plannedIncome}%"></i>`:''}</div>${profile.desiredIncome?`<i class="targetMarker" style="left:${100*profile.desiredIncome/max}%"></i>`:''}</div><b>${money(f.displayedTotal)}</b></div><p class="yearFunding">${f.sources.filter(x=>x.displayAmount>0).map(x=>`${x.label} <b>${money(x.displayAmount)}</b>`).join(' · ')||'No funded income'}${r.shortfall>1?`<span class="unfundedText">Unfunded: <b>${money(f.displayedShortfall)}</b> of ${money(f.displayedPlanned)} planned</span>`:''}</p></div>`}).join('')}${profile.desiredIncome?`<p class="fine">Dashed mark: your original ${money(profile.desiredIncome)} annual target. Hatched amounts are unfunded; they are not included in the income total.</p>`:''}</section>`}
function incomeFunding(o){const early=fundingBreakdown(o.rows.slice(0,10)),later=fundingBreakdown(o.rows.slice(10));const block=(f,title)=>`<section class="fundingPeriod"><h4>${title}</h4><dl>${f.sources.filter(x=>x.amount>0||['accountBasedIncome','lifetimeIncome','agePension'].includes(x.key)).map(x=>`<div><dt><i style="background:${x.colour}"></i>${x.label}</dt><dd>${money(x.displayAmount)}</dd></div>`).join('')}<div class="fundingTotal"><dt>Total funded income</dt><dd>${money(f.displayedTotal)} / yr</dd></div>${f.shortfall>1?`<div class="fundingShortfall"><dt>Unfunded planned income</dt><dd>${money(f.displayedShortfall)} / yr</dd></div><div><dt>Total planned income</dt><dd>${money(f.displayedPlanned)} / yr</dd></div>`:''}</dl></section>`;return `<section class="panel incomeFunding" aria-label="How your income is funded"><h3>How your income is funded</h3><p class="fine">Annual averages, matching the income totals above.</p>${block(early,periodLabel(o,profile.retirementAge))}${later?`<details><summary>Later retirement: ages ${profile.retirementAge+10}–95</summary>${block(later,'Later retirement')}</details>`:''}<p class="fine">Account-based pension income is a withdrawal from your balance, including capital. Withdrawals above planned spending required by minimum rules are kept in savings, not counted again as income.${o.rows.some(r=>r.reserveIncome>1)?' Once invested savings are insufficient, the accessible reserve is drawn too.':''}</p></section>`}
function relevantLimits(){return `<p class="contextNote">${profile.retirementAge>profile.age?`Before retirement: 2% assumed annual growth above inflation; ${profile.annualContributions?`${money(profile.annualContributions)} annual contributions after tax included`:'no future contributions included'}. `:''}${!profile.homeowner?'Rent Assistance is excluded. Include rent in your spending target. ':''}Returns are smooth assumptions; markets and actual product terms can change these results.</p>`}
function uncertainty(o){const low=lowerReturnScenario(profile,prefs,controls);return `<details class="pensionDetail"><summary>What if investment returns are lower?</summary><p>This example lowers invested-savings returns by one percentage point every retirement year, with the same spending preferences. It is a sensitivity check, not a forecast or a probability range.</p><div class="projectionTable"><table><thead><tr><th>Outcome</th><th>Current assumptions</th><th>Lower returns</th></tr></thead><tbody><tr><th>Early average / year</th><td>${money(o.earlyIncome)}</td><td>${money(low.earlyIncome)}</td></tr><tr><th>Later average / year</th><td>${o.laterIncome===null?'Not modelled':money(o.laterIncome)}</td><td>${low.laterIncome===null?'Not modelled':money(low.laterIncome)}</td></tr><tr><th>Savings at 90</th><td>${money(o.futureBalance)}</td><td>${money(low.futureBalance)}</td></tr><tr><th>First spending shortfall</th><td>${o.shortfallAge?`Age ${o.shortfallAge}`:'None to 95'}</td><td>${low.shortfallAge?`Age ${low.shortfallAge}`:'None to 95'}</td></tr></tbody></table></div><p class="fine">Age Pension is recalculated in both cases. With an entered target, a higher estimated Age Pension reduces the savings withdrawal needed to fund it. Lower returns can still bring forward a shortfall or reduce later savings. Without a target, the preference-based spending estimate can change as Age Pension changes. Market falls, their timing, living beyond 95 and changing expenses are still unmodelled.</p></details>`}
function allocationBasis(){return `<div class="contextNote"><strong>An illustration shaped by preferences</strong><p>LIFE percentages come from prototype rules, rather than an assessment of the right allocation for you. The investment label is an assumed setting for the calculations. Neither is a product recommendation or risk assessment.</p><details><summary>How these allocations are generated</summary><p>The buffer preference assigns 5–20% to Life happens. Certainty and access preferences assign 0–40% to a lifetime product. The balance is split between Income for today and Future &amp; family using spending and legacy preferences. These ranges are design assumptions, not optimised allocations.</p><p>The investment setting uses the initial allocations and retirement horizon: more than 40% for Future &amp; family with over 25 years to age 95 uses Growth; at least 19% buffer and 20% lifetime allocation uses Conservative; otherwise Balanced. It stays fixed during exploration. Personal advice can assess investment risk, appropriate allocations and actual lifetime product terms.</p></details></div>`}
function questionsToDiscuss(o){return [o.shortfallAge?`How could I address the unfunded planned income from age ${o.shortfallAge}?`:'Does this income cover my essential costs and the lifestyle I want?',o.rows[0].agePension===0?'How should I fund the years before any Age Pension starts?':'What Age Pension could I actually qualify for?',!profile.homeowner?'Have I allowed enough for rent, and could I qualify for Rent Assistance?':'Have I allowed for housing costs, repairs and future care?',`Is ${money(o.reserve)} an appropriate accessible reserve?`,'What investment risk suits me, and what happens after a market fall?','What are the costs, access restrictions, indexation and death benefits of an actual lifetime product?'];}
function supportPanel(o){return `<section class="panel supportPanel"><h2>Your next step</h2><p>Save your approach, then use it to discuss your income needs and choices. Your summary includes each income source, savings withdrawals, any unfunded amounts, assumptions and these questions.</p><ul>${questionsToDiscuss(o).map(q=>`<li>${q}</li>`).join('')}</ul><a class="secondary supportLink" href="https://hostplus.com.au/members/our-products-and-services/financial-planning-and-advice/financial-advice-options" target="_blank" rel="noopener noreferrer">Explore Hostplus advice options ↗</a><p class="fine">For Hostplus members; eligibility and fees may apply. You can also speak to your own super fund or a qualified financial adviser. This link opens a separate website and does not send your entries.</p></section>`}
function showShortfall(){const {current,options}=shortfallOptions(profile,prefs,controls);showDetail(`<h2>Compare ways to address the gap</h2><p>Compare one change at a time with your current ${money(current.earlyIncome)} early annual average. These examples show consequences; they do not guarantee the target will be met.</p>${options.map(({key,title,outcome:o})=>`<section class="optionCard"><h3>${title}</h3><p>Early average: <b>${money(o.earlyIncome)} / year</b><br>First year: ${money(o.rows[0].spending)}<br>Unfunded early average: ${money(fundingBreakdown(o.rows.slice(0,10)).displayedShortfall)} / year<br>First unfunded year: ${o.shortfallAge?`Age ${o.shortfallAge}`:'None to 95'}<br>Accessible savings at retirement: ${money(o.accessibleCapital)}<br>Money at 90: ${money(o.futureBalance)}</p><p class="fine">${key==='later'?'A later start means fewer retired years. Any entered contributions continue until the new retirement age.':key==='lowerTarget'?'Lower spending reduces withdrawals, but also means a smaller lifestyle budget.':'Less spending early preserves more savings for later. Check the full timeline.'}</p><button class="secondary" data-apply-option="${key}">Try this change</button></section>`).join('')}<section class="optionCard"><h3>Revisit your spending target</h3><p>Check essential costs first, then decide which discretionary spending could change. Lowering the target reduces planned spending and the savings withdrawals needed to fund it; it does not create more money.</p><button class="secondary" data-edit-target>Review my target and contributions</button></section><p>Combine changes in Explore, or discuss the remaining gap with an adviser.</p>`);dialog.querySelectorAll('[data-apply-option]').forEach(b=>b.onclick=()=>{const option=options.find(x=>x.key===b.dataset.applyOption);profile={...option.profile};controls={...option.controls};lastChange=null;lastControl=null;dialog.close();navigate('explore')});dialog.querySelector('[data-edit-target]').onclick=()=>{dialog.close();navigate('about');app.querySelector('[name=desiredIncome]')?.focus()};}

function results(o){return `<div class="incomeHero"><div class="eyebrow" style="color:#a9e4f1">What lifestyle could this support?</div><p style="margin-bottom:0">${periodLabel(o,profile.retirementAge)}</p><div class="bigMoney">${money(o.earlyIncome)}<span class="unit">a year on average</span></div>${o.laterIncome!==null?`<div class="later"><span>Later: ages ${profile.retirementAge+10}–95</span><b>${money(o.laterIncome)}<span class="unit">/ yr average</span></b></div>`:'<div class="later"><span>Projection ends at age 95</span></div>'}<p class="fine" style="color:#bbced9;margin:15px 0 0">Today’s dollars · ${profile.relationshipStatus==='couple'?'combined household':'individual'} amounts · annual averages, not a fixed payment</p></div>${incomeFunding(o)}${incomeTimeline(o)}${targetGuidance(o)}<div class="metrics"><div class="metric"><label>What income continues for life?</label><strong>${money(o.reliableIncome)}<span class="unit">/ yr at retirement</span></strong><small>Age Pension estimate: ${money(o.agePension)}<br>Assumed lifetime product: ${money(o.lifetimeIncome)}${profile.retirementAge<67?`<br>Age Pension at your age 67: ${money(o.agePensionAt67)} / yr`:''}<br>Age Pension can change. Product income assumes CPI indexing.</small></div><div class="metric"><label>What savings remain accessible?</label><strong>${money(o.accessibleCapital)}</strong><small>At retirement, including ${money(o.reserve)} for life’s surprises${profile.knownExpenses?', after known expenses':''}.</small></div></div><details class="pensionDetail"><summary>Reserve and money remaining later</summary><p>Life happens reserve: <b>${money(o.reserve)}</b>, included in accessible savings.<br>Money remaining at age 90: <b>${money(o.futureBalance)}</b> in accessible assets at the start of the year. Lifetime-product death benefits excluded.</p></details>${o.shortfallAge?`<div class="change"><h3>Less room for your lifestyle from age ${o.shortfallAge}</h3><p>Your accessible savings no longer fully support the planned spending. Explore keeping more for later.</p></div>`:''}${relevantLimits()}${uncertainty(o)}${incomeStory(o)}${pensionDetails(o)}${projectionDetails(o)}`}

function structure(o){if(o.s.capital===0)return `<p>No account-based or lifetime product is funded in this example. Any Age Pension and other income are shown separately.</p>`;return `<div class="structure"><span class="pill">${o.s.investmentOption} investment approach</span><span class="pill">Account-based pension</span>${o.a.E>0?'<span class="pill">Some lifetime income</span>':''}</div><details><summary>See the illustrative structure</summary><p class="fine">Retirement capital: ${money(o.s.capital)}<br>Account-based pension: ${money(o.s.accountBasedPension*o.s.pensionFraction)}<br>Other invested savings: ${money(o.s.accountBasedPension*(1-o.s.pensionFraction))}<br>Accessible reserve: ${money(o.s.liquidReserve)}<br>Committed to lifetime income: ${money(o.s.lifetimeIncomeAllocation)}<br>This is a purpose-based illustration, not a Hostplus product offer.</p></details>`}
function explanation(){const o=outcome(baseline),capital=o.s.capital;return [{said:questions[0].options[prefs.earlyLifestyle],means:`About ${money(capital*o.a.I/100)} is assigned to supporting your lifestyle. The first ${o.earlyYearsCount} years average ${money(o.earlyIncome)} a year, including any pension and lifetime income.`},{said:`Unexpected expenses: ${questions[1].options[prefs.emergencySecurity].toLowerCase()}`,means:`We’ve started with ${money(o.reserve)} readily available: ${Math.round(o.a.L)}% of your retirement savings. This reflects your buffer preference and leaves the rest available for other goals.`},{said:`Income certainty: ${questions[2].options[prefs.lifetimeCertainty].toLowerCase()}; access: ${questions[3].options[prefs.liquidity].toLowerCase()}`,means:capital?`We’ve balanced those answers with a ${money(o.s.lifetimeIncomeAllocation)} lifetime commitment (${Math.round(o.a.E)}%). At the assumed payout, that provides ${money(o.lifetimeIncome)} a year and leaves ${money(o.accessibleCapital)} accessible.`:'There are no savings to commit to lifetime income in this example.'},{said:`Family and legacy: ${questions[4].options[prefs.legacy].toLowerCase()}. Later spending: ${questions[5].options[prefs.laterSpending].toLowerCase()}.`,means:`About ${money(capital*o.a.F/100)} is assigned to future needs and family. These priorities affect planned spending, rather than ring-fencing an inheritance.`},{said:'Your retirement horizon and the balance of your goals',means:`${o.s.investmentOption} is the illustrative investment starting point: ${o.s.investmentOption==='Growth'?'a longer horizon and more emphasis on future money':o.s.investmentOption==='Conservative'?'greater emphasis on near-term security':'a middle ground between supporting today and keeping money invested for later'}. It isn’t a risk assessment. We hold it steady while you explore so you can see the effect of your choices.`}]}
function changeText(key,from,to){const a=outcome(from),b=outcome(to);let title={enjoy:to[key]>from[key]?'Enjoy more now':'Keep more for later',certainty:to[key]>from[key]?'More income certainty':'More flexibility',buffer:to[key]>from[key]?'A bigger safety buffer':'More money invested',legacy:to[key]>from[key]?'Leave more behind':'Use more yourself'}[key];if(to[key]===from[key])return {title:'Back to where this adjustment began',gain:'This control is unchanged from the beginning of your adjustment.',cost:'Your other choices are still included in the results.'};if(key==='certainty')return {title,gain:deltaSentence('Lifetime product income',a.lifetimeIncome,b.lifetimeIncome,true),cost:deltaSentence('Savings you can access',a.accessibleCapital,b.accessibleCapital),extra:deltaSentence('Age Pension at retirement',a.agePension,b.agePension,true)};if(key==='buffer')return {title,gain:deltaSentence('Your accessible reserve',a.reserve,b.reserve),cost:deltaSentence('Average early annual spending',a.earlyIncome,b.earlyIncome,true),extra:deltaSentence('Money remaining at 90',a.futureBalance,b.futureBalance)};return {title,gain:deltaSentence('Average early annual spending',a.earlyIncome,b.earlyIncome,true),cost:deltaSentence('Money remaining at 90',a.futureBalance,b.futureBalance)};}
function changeCard(t){return `<h3>${t.title}</h3><p class="gain">${t.gain}</p><p>${t.cost}</p>${t.extra?`<p>${t.extra}</p>`:''}`}
function welcome(){return `<div class="welcome"><section class="welcomeCopy"><div class="eyebrow">YOUR RETIREMENT. YOUR PRIORITIES.</div><h1 tabindex="-1"><span>Your next chapter.</span><em>A clearer starting point.</em></h1><p class="lead">You don’t need to have it all figured out. Tell us a little about you and what matters in retirement. We’ll help you see what could work.</p><div class="actions"><button class="primary" data-nav="about">Get started</button></div><p class="small">A few simple questions. Space to explore.</p></section><section class="lifeTower" aria-label="The four LIFE goals"><div class="towerHeading"><span>FOUR PURPOSES. ONE LIFE.</span><span aria-hidden="true">01 — 04</span></div>${goals.map((g,i)=>`<div class="towerItem" style="--colour:${g.colour}"><div class="letter">${g.key}</div><div><strong>${g.title}</strong><p>${{L:'Room for life’s surprises.',I:'The lifestyle you want to enjoy.',F:'For later life and the people you love.',E:'Income that goes the distance.'}[g.key]}</p></div><span class="goalIndex" aria-hidden="true">0${i+1}</span></div>`).join('')}<div class="towerFoot">Your priorities provide the direction.</div></section></div>`}
function field(key,title,note='',min=0,max=100000000){return `<label class="field">${title}<input name="${key}" type="number" min="${min}" max="${max}" step="${key==='lifetimePayout'?0.1:1}" value="${profile[key]??0}">${note?`<small>${note}</small>`:''}</label>`}
function about(){return `<section class="narrow"><div class="eyebrow">01 / Understand you</div><h1 tabindex="-1">A little about you.</h1><p>Rough figures are fine. We’ve added example values you can change. Future contributions are only included if you enter them.</p><form id="profileForm" class="panel"><div class="formGrid">${field('age','Your age','',18,89)}${field('retirementAge','Planned retirement age','Already retired? Use your current age. This prototype models retirement from 60.',60,89)}<label class="field">Planning for<select name="relationshipStatus"><option value="single" ${profile.relationshipStatus==='single'?'selected':''}>Just me</option><option value="couple" ${profile.relationshipStatus==='couple'?'selected':''}>Me and my partner</option></select></label><label class="field">Your home<select name="homeowner"><option value="true" ${profile.homeowner?'selected':''}>I own my home</option><option value="false" ${!profile.homeowner?'selected':''}>I don’t own my home</option></select></label>${field('superBalance','Your super balance ($)')}${field('annualContributions','Annual contributions until retirement ($) — optional','Amount credited to super each year after contributions tax, in today’s dollars. Combined for a couple. Default 0; employer and personal contributions are not added automatically.')}<div id="partnerField" ${profile.relationshipStatus==='single'?'hidden':''}>${field('partnerSuper','Partner’s super balance ($)','We assume you retire together.')}<div style="margin-top:20px">${field('partnerAge','Partner’s current age','Used to work out when their Age Pension could start.',18,99)}</div></div></div><div style="margin-top:22px">${field('desiredIncome','Annual retirement income target ($) — optional','Starting spending budget. Pensions and savings withdrawals fund it. Leave blank for a preference-based estimate. Combined for a couple.')}</div><details><summary>Add anything else (optional)</summary><div class="formGrid">${field('otherAssets','Other financial assets ($)','Savings and investments outside super.')}${field('knownExpenses','Known large future expenses ($)','Deducted once at retirement, before setting up the plan.')}${field('nonFinancialAssets','Other assessable assets ($)','Car, contents and net non-home property value. Excludes your main home.')}${field('otherIncome','Other annual assessable income ($)','For example net rent or a non-employment pension. No Work Bonus applied.')}<label class="field">Include Age Pension?<select name="pensionExpectation"><option value="estimate" ${profile.pensionExpectation==='estimate'?'selected':''}>Yes — estimate from the means tests</option><option value="eligible" ${profile.pensionExpectation==='eligible'?'selected':''}>Yes — I believe I meet residence rules</option><option value="none" ${profile.pensionExpectation==='none'?'selected':''}>Exclude Age Pension</option></select><small>Assumes residence rules are met. Entitlement is calculated, not assumed from your answer.</small></label></div><details><summary>Advanced prototype assumption</summary>${field('lifetimePayout','Illustrative lifetime payout (%)','Default 5.5%, assumed CPI indexed. An assumption, not a product quote.',3,10)}</details></details><p id="housingNote" class="contextNote">${profile.homeowner?'Allow for housing costs, repairs and any mortgage in your spending target.':'Include rent in your target. Rent Assistance is excluded, so eligible renters may receive more than this estimate.'} Tax, debt repayments and actual lifetime product prices are not calculated.</p><div id="formError" role="alert"></div><div class="actions"><button class="primary" type="submit">${preferencesDone?'Update my results':'What matters to you'}</button><button class="textButton" type="button" data-nav="welcome">Back</button></div></form></section>`}
function preference(){const q=questions[question];return `<section class="narrow"><div class="eyebrow">02 / What matters</div><div class="questionDots">${questions.map((_,i)=>`<i class="${i<=question?'on':''}"></i>`).join('')}</div><div class="questionCount">Question ${question+1} of 6</div><h1 tabindex="-1">${q.title}</h1><p>There’s no right answer. Choose what feels closest to you.</p>${preferencesDone?'<p class="fine">Updating these priorities creates a fresh starting point and resets exploration adjustments.</p>':''}<div role="radiogroup" aria-label="${q.title}">${q.options.map((option,i)=>`<button role="radio" tabindex="${chosen===i||(chosen===null&&i===0)?0:-1}" aria-checked="${chosen===i}" class="choice ${chosen===i?'selected':''}" data-choice="${i}"><span class="radio"></span><span>${option}</span></button>`).join('')}</div><div class="actions"><button id="nextQuestion" class="primary" ${chosen===null?'disabled style="opacity:.45"':''}>${question===5?'See my starting point':'Continue'}</button><button id="backQuestion" class="textButton">Back</button></div></section>`}
function starting(){const o=outcome(baseline);return `<div class="intro"><div><div class="eyebrow">03 / Your starting point</div><h1 tabindex="-1">Here’s a starting point based on what you told us.</h1><p>Something to explore, shaped around your priorities.</p></div></div><div class="resultGrid"><section>${results(o)}</section><section class="panel">${life(o)}${allocationBasis()}${structure(o)}</section></div><section class="panel why"><h2>Why this starting point?</h2><div class="whyRow" style="padding-bottom:8px;border:0"><strong>What you told us</strong><strong>How we’ve reflected it</strong></div>${explanation().map(r=>`<div class="whyRow"><p>${r.said}</p><p>${r.means}</p></div>`).join('')}</section><div class="actions"><button class="primary" data-nav="explore">Explore your options</button><button class="secondary" data-nav="about">Edit your details</button><button class="textButton" data-edit-priorities>Edit your priorities</button></div>`}
function mobileSnapshot(o){const a=outcome(baseline);return `<div class="snapshotLabel">Live outcomes <span>Today’s dollars · prototype</span></div><div class="snapshotFigures"><div><span>Early spending / yr</span><strong>${money(o.earlyIncome)}</strong><small>${Math.abs(o.earlyIncome-a.earlyIncome)<50?'Little change':`${money(Math.abs(o.earlyIncome-a.earlyIncome))} ${o.earlyIncome>a.earlyIncome?'more':'less'}`}</small></div><div><span>Accessible savings</span><strong>${money(o.accessibleCapital)}</strong><small>${Math.abs(o.accessibleCapital-a.accessibleCapital)<100?'Little change':`${money(Math.abs(o.accessibleCapital-a.accessibleCapital))} ${o.accessibleCapital>a.accessibleCapital?'more':'less'}`}</small></div></div>`}
function comparison(){if(sameControls(controls,baseline))return 'You’re at your original starting point.';const a=outcome(baseline),b=outcome();return `Your approach has changed. ${deltaSentence('Average early annual spending',a.earlyIncome,b.earlyIncome,true)} ${deltaSentence('Savings you can access',a.accessibleCapital,b.accessibleCapital)}`}
function combinedComparison(){const a=outcome(baseline),b=outcome();return `<div class="beforeAfter"><div class="compareHeading"><span>Outcome</span><span>Starting point</span><span>Your approach</span></div>${[{key:'earlyIncome',title:'Early spending / year',annual:true},{key:'laterIncome',title:'Later spending / year',annual:true},{key:'lifetimeIncome',title:'Lifetime product / year',annual:true},{key:'agePension',title:'Age Pension at retirement / year',annual:true},{key:'accessibleCapital',title:'Accessible savings'},{key:'reserve',title:'Safety reserve'},{key:'futureBalance',title:'Money at age 90'}].map(x=>`<div class="compareRow"><div><strong>${x.title}</strong><small>${deltaSentence(x.title,a[x.key],b[x.key],x.annual)}</small></div><span>${a[x.key]===null?'Not modelled':money(a[x.key])}</span><b>${b[x.key]===null?'Not modelled':money(b[x.key])}</b></div>`).join('')}</div>`}
function explore(){const o=outcome();return `<div class="intro"><div><div class="eyebrow">04 / Explore the trade-offs</div><h1 tabindex="-1">Find the balance that feels like you.</h1><p>Change what matters. See both sides, straight away.</p></div><button class="secondary" id="reset">Reset to starting point</button></div><aside id="mobileSnapshot" class="mobileSnapshot" aria-label="Live outcome summary">${mobileSnapshot(o)}</aside><div class="exploreGrid"><section class="panel controls">${tradeoffs.map(t=>`<div class="control"><h3>${t.title}</h3><div class="ends"><span>${t.left}</span><span>${t.right}</span></div><input type="range" min="0" max="100" value="${controls[t.key]}" id="${t.key}" data-control="${t.key}" aria-label="${t.title}: ${t.left} to ${t.right}" aria-valuetext="${controls[t.key]} out of 100"><p class="hint">${t.hint}</p><div class="inlineChange" id="change-${t.key}" ${lastControl===t.key&&lastChange?'':'hidden'}>${lastControl===t.key&&lastChange?changeCard(lastChange):''}</div></div>`).join('')}<div id="change" class="change" role="status" aria-live="polite">${lastChange?changeCard(lastChange):sameControls(controls,baseline)?'<h3>You’re at your starting point.</h3><p>Move a control to see what changes.</p>':'<h3>Your choices are still here.</h3><p>The results include all your adjustments. Review them against your starting point below.</p>'}</div><div class="actions"><button class="primary" data-nav="changed">Review my changes</button><button class="textButton" data-nav="about">Edit details</button><button class="textButton" data-edit-priorities>Edit priorities</button></div></section><section class="sticky"><div id="liveResults">${results(o)}</div><div class="panel" style="margin-top:16px"><div id="liveLife">${life(o)}</div><div id="liveStructure">${allocationBasis()}${structure(o)}</div></div><div id="compare" class="compare">${comparison()}</div></section></div>`}
function changed(){const changedControls=tradeoffs.filter(t=>controls[t.key]!==baseline[t.key]);return `<section class="narrow"><div class="eyebrow">05 / What changed</div><h1 tabindex="-1">Your choices, made visible.</h1><p>${changedControls.length?'This is the combined result of all your choices, compared with your starting point.':'You’ve kept your starting point. That’s a valid choice too.'}</p><section class="panel">${combinedComparison()}</section>${changedControls.length?`<div class="summaryHead" style="margin-top:20px"><h3>What you’ve moved towards</h3><p>${changedControls.map(t=>controls[t.key]>baseline[t.key]?t.right:t.left).join(' · ')}</p></div>`:''}<p class="fine">The reserve is part of accessible savings. Age Pension changes over time; it isn’t added twice to your spending figures.</p><div class="actions"><button class="primary" data-nav="summary">See my approach</button><button class="secondary" data-nav="explore">Keep exploring</button></div></section>`}
function summary(){const o=outcome();return `<div class="intro"><div><div class="eyebrow">06 / Your approach</div><h1 tabindex="-1">A clearer place to start.</h1><p>Your priorities, brought together in one approach.</p></div><button class="secondary" data-nav="explore">Adjust my approach</button></div><div class="summaryHead"><h3>Your current retirement priorities</h3><p>${currentPriorities(controls)}</p></div><div class="resultGrid"><section>${results(o)}</section><section class="panel">${life(o)}${allocationBasis()}${structure(o)}<details><summary>How this compares with my starting point</summary>${combinedComparison()}</details><details><summary>What would be worth checking next?</summary><p class="fine">Whether your income target covers your needs; actual Age Pension eligibility; investment risk; and the costs, access conditions and death benefits of any lifetime product. Personal advice can help you decide what suits your circumstances.</p></details></section></div>${supportPanel(o)}<div class="actions"><button class="primary" id="save">Save this approach</button><button class="secondary" id="talk">Talk to someone</button><button class="textButton" data-nav="about">Edit details</button><button class="textButton" data-edit-priorities>Edit priorities</button><button class="textButton" id="restart">Start again</button></div><div id="saveMessage" class="saved" role="status">${saved?'Your summary has been downloaded.':''}</div>`}
let previousScene='';
function render(){const stages=[['about','You'],['preference','Priorities'],['starting','Starting point'],['explore','Explore'],['summary','Your approach']],active=screen==='changed'?'explore':screen;document.querySelector('#progress').innerHTML=screen==='welcome'?'<span class="welcomeProgress">A starting point. A world of possibilities.</span>':`<ol class="chapterRail" aria-label="Your journey">${stages.map(([key,label],i)=>`<li ${active===key?'aria-current="step"':''} class="${active===key?'active':''}"><span class="chapterNumber">0${i+1}</span><span class="chapterLabel">${label}</span></li>`).join('')}</ol>`;app.dataset.screen=screen;app.innerHTML={welcome,about,preference,starting,explore,changed,summary}[screen]();bind();const scene=screen+(screen==='preference'?question:'');if(scene!==previousScene&&typeof app.animate==='function'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){app.getAnimations().forEach(a=>a.cancel());app.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:440,easing:'cubic-bezier(.2,.7,.2,1)'});}previousScene=scene;}
function bindResultActions(){app.querySelectorAll('[data-shortfall]').forEach(b=>b.onclick=showShortfall);app.querySelectorAll('[data-target-explore]').forEach(b=>b.onclick=()=>{if(screen!=='explore')navigate('explore');app.querySelector('#enjoy')?.focus({preventScroll:true});app.querySelector('#enjoy')?.closest('.control').scrollIntoView({block:'center',behavior:'smooth'})});}
function bind(){bindResultActions();app.querySelectorAll('[data-edit-priorities]').forEach(b=>b.onclick=()=>{question=0;draftPreferences={...prefs};chosen=prefs[questions[0].key];navigate('preference')});app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));app.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{const g=goals.find(g=>g.key===b.dataset.goal);showDetail(`<div class="eyebrow" style="color:${g.colour}">${g.key} / LIFE</div><h2>${g.title}</h2><p>${g.desc}</p>`)});if(screen==='about'){app.querySelector('[name=homeowner]').onchange=e=>{app.querySelector('#housingNote').textContent=e.target.value==='false'?'Include rent in your target. Rent Assistance is excluded, so eligible renters may receive more than this estimate. Tax, debt repayments and actual lifetime product prices are not calculated.':'Allow for housing costs, repairs and any mortgage in your spending target. Tax, debt repayments and actual lifetime product prices are not calculated.'};app.querySelector('[name=relationshipStatus]').onchange=e=>{app.querySelector('#partnerField').hidden=e.target.value==='single'};app.querySelector('#profileForm').onsubmit=e=>{e.preventDefault();let data=new FormData(e.target),next={...profile};for(const [k,v] of data)next[k]=['relationshipStatus','pensionExpectation'].includes(k)?v:k==='homeowner'?v==='true':v.trim()===''?(k==='desiredIncome'||k==='annualContributions'?0:defaults[k]):Number(v);if(next.retirementAge<next.age||next.retirementAge<60){app.querySelector('#formError').innerHTML='<p class="formError">Use a retirement age of at least 60 and at or above your current age.</p>';return}if(next.relationshipStatus==='couple'&&next.partnerAge+next.retirementAge-next.age<60){app.querySelector('#formError').innerHTML='<p class="formError">This prototype assumes you both retire at 60 or older. Increase your planned retirement age or check your partner’s age.</p>';return}if(next.knownExpenses>grossRetirementCapital(next)){app.querySelector('#formError').innerHTML='<p class="formError">Your known expenses exceed the estimated savings available at retirement. Check the amount.</p>';return}profile=next;lastChange=null;lastControl=null;if(preferencesDone){baseline=initialControls(prefs);navigate('explore')}else{question=0;draftPreferences={...prefs};chosen=null;navigate('preference')}}}if(screen==='preference'){app.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.choice);const active=chosen;render();app.querySelector(`[data-choice="${active}"]`).focus()});app.querySelector('[role=radiogroup]').onkeydown=e=>{if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft'].includes(e.key)){e.preventDefault();chosen=((chosen??0)+(e.key==='ArrowDown'||e.key==='ArrowRight'?1:2))%3;render();app.querySelector(`[data-choice="${chosen}"]`).focus()}};app.querySelector('#nextQuestion').onclick=()=>{if(chosen===null)return;draftPreferences[questions[question].key]=chosen;if(question<5){question++;chosen=preferencesDone?draftPreferences[questions[question].key]:null;render();app.querySelector('h1').focus()}else{prefs={...draftPreferences};preferencesDone=true;controls=initialControls(prefs);baseline={...controls};lastChange=null;lastControl=null;navigate('starting')}};app.querySelector('#backQuestion').onclick=()=>{if(question===0)navigate('about');else{question--;chosen=draftPreferences[questions[question].key];render()}}}if(screen==='explore'){app.querySelector('#reset').onclick=()=>{controls={...baseline};lastChange=null;lastControl=null;render()};app.querySelectorAll('[data-control]').forEach(input=>{let before={...controls};input.addEventListener('pointerdown',()=>before={...controls});input.addEventListener('keydown',()=>before={...controls});input.oninput=()=>{const key=input.dataset.control;controls={...controls,[key]:Number(input.value)};input.setAttribute('aria-valuetext',`${input.value} out of 100`);lastChange=changeText(key,before,controls);lastControl=key;app.querySelector('#liveResults').innerHTML=results(outcome());app.querySelector('#liveLife').innerHTML=life(outcome());app.querySelector('#liveStructure').innerHTML=allocationBasis()+structure(outcome());app.querySelector('#change').innerHTML=changeCard(lastChange);app.querySelector('#compare').innerHTML=comparison();app.querySelector('#mobileSnapshot').innerHTML=mobileSnapshot(outcome());app.querySelectorAll('.inlineChange').forEach(el=>el.hidden=true);const inline=app.querySelector(`#change-${key}`);inline.hidden=false;inline.innerHTML=changeCard(lastChange);bindResultActions();app.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{let g=goals.find(g=>g.key===b.dataset.goal);showDetail(`<h2>${g.title}</h2><p>${g.desc}</p>`)})}})}if(screen==='summary'){app.querySelector('#save').onclick=save;app.querySelector('#talk').onclick=()=>showDetail(supportPanel(outcome()));app.querySelector('#restart').onclick=()=>{profile={...defaults};prefs={...defaultPreferences};controls=initialControls(prefs);baseline={...controls};question=0;chosen=null;lastChange=null;lastControl=null;preferencesDone=false;draftPreferences={...prefs};navigate('welcome')}}}
function save(){const o=outcome(),text=`LIFE — Your retirement approach\nPrototype only. Not financial advice or a validated projection.\nAll figures are in today's dollars and are illustrative.\n\nAge: ${profile.age} | Retirement age: ${profile.retirementAge} | ${profile.relationshipStatus}\n\nYOUR CURRENT PRIORITIES\n${currentPriorities(controls)}\n\nCHANGES FROM YOUR STARTING POINT\n${comparison()}\n${[{key:'earlyIncome',label:'Average early annual spending'},{key:'laterIncome',label:'Average later annual spending'},{key:'lifetimeIncome',label:'Lifetime product income per year'},{key:'agePension',label:'Age Pension at retirement per year'},{key:'accessibleCapital',label:'Accessible savings'},{key:'reserve',label:'Safety reserve'},{key:'futureBalance',label:'Money remaining at age 90'}].map(({key,label})=>`${label}: ${outcome(baseline)[key]===null?'Not modelled':money(outcome(baseline)[key])} → ${o[key]===null?'Not modelled':money(o[key])}`).join('\n')}\n\nYOUR CURRENT APPROACH\n${o.s.capital===0?'No savings available to allocate.':goals.map(g=>`${g.title}: ${o.a[g.key].toFixed(1)}%`).join('\n')}\nInvestment approach: ${o.s.investmentOption}\nRetirement capital: ${money(o.s.capital)}\nAccount-based / invested savings: ${money(o.s.accountBasedPension)}\nReserve: ${money(o.reserve)}\nCommitted to lifetime income: ${money(o.s.lifetimeIncomeAllocation)}\n\nILLUSTRATIVE OUTCOMES\n${periodLabel(o,profile.retirementAge)} average annual spending: ${money(o.earlyIncome)}\nAverage later annual spending (through 95): ${o.laterIncome===null?'No later period in this projection':money(o.laterIncome)}\nLifetime product income: ${money(o.lifetimeIncome)} a year\nIndicative Age Pension at retirement: ${money(o.agePension)} a year\nAccessible savings at retirement: ${money(o.accessibleCapital)}\nRemaining assets at 90: ${money(o.futureBalance)}\n\nHOW YOUR INCOME IS FUNDED (ANNUAL AVERAGES)\n${[ {title:periodLabel(o,profile.retirementAge),rows:o.rows.slice(0,10)}, {title:'Later retirement',rows:o.rows.slice(10)} ].filter(p=>p.rows.length).map(p=>{const f=fundingBreakdown(p.rows);return p.title+'\n'+f.sources.map(x=>`${x.label}: ${money(x.displayAmount)}`).join('\n')+`\nTotal funded: ${money(f.displayedTotal)}\nUnfunded: ${money(f.displayedShortfall)}`}).join('\n\n')}\n\nCURRENT TRADE-OFF POSITIONS (0–100)\n${tradeoffs.map(t=>`${t.title}: ${controls[t.key]} (${t.left} to ${t.right})`).join('\n')}\n\nORIGINAL QUESTIONNAIRE ANSWERS\n${questions.map(q=>`${q.title}\n${q.options[prefs[q.key]]}`).join('\n\n')}\n\nINCOME AT KEY AGES\n${timelineRows(o,profile.retirementAge).map(r=>`Age ${r.age}: ${money(r.spending)} funded income / year; ${fundingBreakdown([r]).sources.map(x=>`${x.label} ${money(x.displayAmount)}`).join('; ')}; unfunded ${money(r.shortfall)}`).join('\n')}\nAnnual target: ${profile.desiredIncome?money(profile.desiredIncome):'Not entered'}\nEarly average unfunded: ${money(fundingBreakdown(o.rows.slice(0,10)).displayedShortfall)}\n\nQUESTIONS FOR YOUR ADVICE CONVERSATION\n${questionsToDiscuss(o).map(q=>'- '+q).join('\n')}\nAdvice options: https://hostplus.com.au/members/our-products-and-services/financial-planning-and-advice/financial-advice-options\n\nLOWER RETURN SENSITIVITY (1 percentage point lower each retirement year; not a probability range)\nEarly average: ${money(lowerReturnScenario(profile,prefs,controls).earlyIncome)}\nSavings at 90: ${money(lowerReturnScenario(profile,prefs,controls).futureBalance)}\n\nALLOCATION BASIS\nPrototype preference rules; not an optimised allocation or risk assessment. Life happens 5–20%, lifetime commitment 0–40%; remaining money split by spending and family priorities. Investment setting derived from initial allocations and horizon; held fixed during exploration.\n\nASSUMPTIONS\nYear-by-year deterministic projection to age 95. 2% real growth on super before retirement, ${money(profile.annualContributions??0)} annual contributions after tax until retirement. Partner age is used; both retire together. Lifetime payout ${profile.lifetimePayout}%, assumed CPI indexed, not a quote. Age Pension rules snapshot 20 September 2026: both income and assets tests, deeming, qualifying lifetime 60% income / 60% assets then 30% assets from age 85 or five years after commencement (whichever later). Future rates and thresholds held constant in real terms; nominal lifetime purchase-price assessment deflated at 2.5% inflation. Residence eligibility assumed. No Rent Assistance, tax, transfer balance cap, grandfathering, market shocks or actual product death benefits. Approximate asset taper without legislative rounding. Real annual net investment returns: Growth 3%, Balanced 2%, Conservative 1%; cash 0%. Minimum ABP withdrawals above planned spending reinvested in cash. Known expenses deducted once before allocation.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='LIFE-retirement-approach.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);saved=true;app.querySelector('#saveMessage').textContent='Your approach has been downloaded. Keep it as a conversation starter.'}
document.querySelector('#prototypeInfo').onclick=()=>document.querySelector('#assumptions').click();
document.querySelector('#home').onclick=()=>navigate('welcome');document.querySelector('#closeDetail').onclick=()=>dialog.close();document.querySelector('#assumptions').onclick=()=>showDetail(`<h2>How the numbers work</h2><p>Age Pension rules checked on 5 October 2026, using the snapshot effective ${RULES.asAt}. The wider retirement projection remains illustrative.</p><ul><li>Both means tests run every year. The lower payment applies. Each partner becomes age eligible at 67. Residence rules are assumed to be met.</li><li>The main home is excluded. All other entered assets are assessed; financial assets are deemed at 1.75% / 3.75%. Account-based pension withdrawals themselves are not added again as assessable income.</li><li>We assume new, immediate lifetime income streams that qualify for the standard treatment: 60% of payments as income; 60% of purchase price as assets, then 30% at age 85 or five years after commencement, whichever is later. Higher capital access or death benefits can change that treatment.</li><li>Lifetime income uses your assumed ${profile.lifetimePayout}% payout, held steady in today’s dollars (CPI indexed). It is not a quoted rate or an investment return. No surrender value or death benefit is included.</li><li>Annual cash flows run to age 95. First-10-year and later figures are averages. Savings at 90 come from the same cash flows. An entered income target sets the initial early budget; exploration changes planned spending. Lifetime income, Age Pension and other income are counted first, then savings withdrawals fund the remainder. Any unfunded amount is shown explicitly. Minimum pension payments above lifestyle spending are retained in cash.</li><li>Super grows at 2% real before retirement, with your entered annual contributions after tax (default 0). Retirement returns are 3% Growth, 2% Balanced or 1% Conservative after assumed costs; cash 0% real. These are assumptions, not forecasts.</li><li>Known expenses are deducted once at retirement. Financial assets outside super remain proportionally outside the pension; minimum withdrawal rules apply to the pension share only.</li><li>Future pension rates and thresholds stay constant in today’s dollars. Original lifetime purchase-price assessment is reduced in real terms with 2.5% assumed inflation. Other assets and other income stay constant in real terms.</li><li>Tax, transfer balance caps, Rent Assistance, Work Bonus, grandfathering, defined benefit rules, mortality and market fluctuations are excluded. Retirement must start at 60 or later for both partners. Annual timing and pension taper rounding are approximate.</li></ul><details><summary>Official rule sources</summary><ul>${SOURCES.map(x=>`<li><a href="${x.url}" target="_blank" rel="noopener noreferrer">${x.title}</a></li>`).join('')}</ul></details><p>Your entries stay in this page and are cleared when you reload.</p>`);
render();
